{
  "items": [
    {
      "name": "MvPolynomial.aeval_natDegree_le",
      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type v} {R : Type u_2} [inst : CommSemiring R] {m n : ℕ} (F : MvPolynomial σ R),\n  F.totalDegree ≤ m →\n    ∀ (f : σ → Polynomial R), (∀ (i : σ), (f i).natDegree ≤ n) → ((MvPolynomial.aeval f) F).natDegree ≤ m * n"
    },
    {
      "name": "MvPolynomial.degreeOf_le_totalDegree",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (f : MvPolynomial σ R) (i : σ),\n  MvPolynomial.degreeOf i f ≤ f.totalDegree"
    },
    {
      "name": "MvPolynomial.degreeOf",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → σ → MvPolynomial σ R → ℕ"
    },
    {
      "name": "MvPolynomial.IsHomogeneous.totalDegree_le",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R] {φ : MvPolynomial σ R} {n : ℕ},\n  φ.IsHomogeneous n → φ.totalDegree ≤ n"
    },
    {
      "name": "MvPolynomial.totalDegree",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → ℕ"
    }
  ]
}
